#[allow(dead_code)]
pub struct IdlTreeWalker;

#[allow(dead_code)]
impl IdlTreeWalker {
    pub fn walk<E, T: IdlListener<E>>(
        listener: &mut T,
        tree: antlr4_runtime::Node<'_>,
    ) -> Result<(), E> {
        Self::__walk(listener, tree, None)
    }

    pub fn walk_with_invocation_states<E, T: IdlListener<E>>(
        listener: &mut T,
        tree: antlr4_runtime::Node<'_>,
        parent_invocation_states: Vec<isize>,
    ) -> Result<(), E> {
        Self::__walk(listener, tree, Some(parent_invocation_states))
    }

    fn __walk<E, T: IdlListener<E>>(
        listener: &mut T,
        tree: antlr4_runtime::Node<'_>,
        mut invocation_states: Option<Vec<isize>>,
    ) -> Result<(), E> {
        enum Event<'tree> {
            Enter(antlr4_runtime::Node<'tree>),
            Exit(RuleNodeView<'tree>),
        }

        let mut stack = vec![Event::Enter(tree)];
        while let Some(event) = stack.pop() {
            match event {
                Event::Enter(node) => match node.kind() {
                    antlr4_runtime::NodeKind::Rule => {
                        let context = node.as_rule().expect("rule node kind checked");
                        if let Some(states) = &mut invocation_states {
                            states.insert(0, context.invoking_state());
                        }
                        listener.enter_every_rule(context)?;
                        match __context_kind(context) {
                        0 => listener.enter_idl_file(&IdlFileContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        1 => listener.enter_protocol_declaration(&ProtocolDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        2 => listener.enter_protocol_declaration_body(&ProtocolDeclarationBodyContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        3 => listener.enter_namespace_declaration(&NamespaceDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        4 => listener.enter_main_schema_declaration(&MainSchemaDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        5 => listener.enter_identifier(&IdentifierContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        6 => listener.enter_schema_property(&SchemaPropertyContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        7 => listener.enter_import_statement(&ImportStatementContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        8 => listener.enter_named_schema_declaration(&NamedSchemaDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        9 => listener.enter_fixed_declaration(&FixedDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        10 => listener.enter_enum_declaration(&EnumDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        11 => listener.enter_enum_symbol(&EnumSymbolContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        12 => listener.enter_enum_default(&EnumDefaultContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        13 => listener.enter_record_declaration(&RecordDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        14 => listener.enter_record_body(&RecordBodyContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        15 => listener.enter_field_declaration(&FieldDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        16 => listener.enter_variable_declaration(&VariableDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        17 => listener.enter_message_declaration(&MessageDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        18 => listener.enter_formal_parameter(&FormalParameterContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        19 => listener.enter_result_type(&ResultTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        20 => listener.enter_full_type(&FullTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        21 => listener.enter_plain_type(&PlainTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        22 => listener.enter_nullable_type(&NullableTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        23 => listener.enter_primitive_type(&PrimitiveTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        24 => listener.enter_array_type(&ArrayTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        25 => listener.enter_map_type(&MapTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        26 => listener.enter_union_type(&UnionTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        27 => listener.enter_json_value(&JsonValueContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        28 => listener.enter_json_literal(&JsonLiteralContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        29 => listener.enter_json_object(&JsonObjectContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        30 => listener.enter_json_pair(&JsonPairContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        31 => listener.enter_json_array(&JsonArrayContext::__from_listener_node(context, invocation_states.as_deref()))?,
                            _ => {}
                        }
                        stack.push(Event::Exit(context));
                        stack.extend(context.children().rev().map(Event::Enter));
                    }
                    antlr4_runtime::NodeKind::Terminal => {
                        listener.visit_terminal(&TerminalNode::new(
                            node.as_terminal().expect("terminal node kind checked"),
                        ))?;
                    }
                    antlr4_runtime::NodeKind::Error => {
                        listener.visit_error_node(&ErrorNode::new(
                            node.as_error().expect("error node kind checked"),
                        ))?;
                    }
                },
                Event::Exit(context) => {
                    match __context_kind(context) {
                    0 => listener.exit_idl_file(&IdlFileContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    1 => listener.exit_protocol_declaration(&ProtocolDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    2 => listener.exit_protocol_declaration_body(&ProtocolDeclarationBodyContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    3 => listener.exit_namespace_declaration(&NamespaceDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    4 => listener.exit_main_schema_declaration(&MainSchemaDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    5 => listener.exit_identifier(&IdentifierContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    6 => listener.exit_schema_property(&SchemaPropertyContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    7 => listener.exit_import_statement(&ImportStatementContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    8 => listener.exit_named_schema_declaration(&NamedSchemaDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    9 => listener.exit_fixed_declaration(&FixedDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    10 => listener.exit_enum_declaration(&EnumDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    11 => listener.exit_enum_symbol(&EnumSymbolContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    12 => listener.exit_enum_default(&EnumDefaultContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    13 => listener.exit_record_declaration(&RecordDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    14 => listener.exit_record_body(&RecordBodyContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    15 => listener.exit_field_declaration(&FieldDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    16 => listener.exit_variable_declaration(&VariableDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    17 => listener.exit_message_declaration(&MessageDeclarationContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    18 => listener.exit_formal_parameter(&FormalParameterContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    19 => listener.exit_result_type(&ResultTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    20 => listener.exit_full_type(&FullTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    21 => listener.exit_plain_type(&PlainTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    22 => listener.exit_nullable_type(&NullableTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    23 => listener.exit_primitive_type(&PrimitiveTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    24 => listener.exit_array_type(&ArrayTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    25 => listener.exit_map_type(&MapTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    26 => listener.exit_union_type(&UnionTypeContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    27 => listener.exit_json_value(&JsonValueContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    28 => listener.exit_json_literal(&JsonLiteralContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    29 => listener.exit_json_object(&JsonObjectContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    30 => listener.exit_json_pair(&JsonPairContext::__from_listener_node(context, invocation_states.as_deref()))?,
                    31 => listener.exit_json_array(&JsonArrayContext::__from_listener_node(context, invocation_states.as_deref()))?,
                        _ => {}
                    }
                    listener.exit_every_rule(context)?;
                    if let Some(states) = &mut invocation_states {
                        states.remove(0);
                    }
                }
            }
        }
        Ok(())
    }
}

